function makeTraffic(color=0x3d7fc2){const g=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color,roughness:.55}),dark=new THREE.MeshStandardMaterial({color:0x1a2226});const body=new THREE.Mesh(new THREE.CylinderGeometry(1.2,1.2,18,16),mat);body.rotation.x=Math.PI/2;g.add(body);const nose=new THREE.Mesh(new THREE.SphereGeometry(1.2,14,9),mat);nose.scale.z=.7;nose.position.z=-9;g.add(nose);const wing=new THREE.Mesh(new THREE.BoxGeometry(18,.16,3.7),mat);g.add(wing);const tail=new THREE.Mesh(new THREE.BoxGeometry(6,.14,2),mat);tail.position.z=7.4;g.add(tail);for(const x of[-3.7,3.7]){const eng=new THREE.Mesh(new THREE.CylinderGeometry(.55,.62,2,12),dark);eng.rotation.x=Math.PI/2;eng.position.set(x,-.7,-.5);g.add(eng)}return g}
for(let i=0;i<7;i++){const model=makeTraffic([0x2474a6,0xd34b3f,0xeeeeee,0xe0a52c][i%4]),lane=i%3-1,phase=i/7,mode=i%3;scene.add(model);traffic.push({model,lane,phase,mode,x:lane*330,z:-3600+phase*5600,y:mode===0?2.8:mode===1?120:700,speed:mode===0?18:75})}
const mountainMat=new THREE.MeshStandardMaterial({color:0x596050,roughness:1});for(let i=0;i<18;i++){const height=480+Math.random()*950,mountain=new THREE.Mesh(new THREE.ConeGeometry(280+Math.random()*520,height,7),mountainMat);mountain.position.set((i%2?-1:1)*(3500+Math.random()*6000),height/2,-3000-Math.random()*15000);scene.add(mountain);obstacles.push({x:mountain.position.x,z:mountain.position.z,r:380,height,type:'山体'})}
