function explosionSound(){if(!state.sound)return;initAudio();const length=Math.floor(audio.sampleRate*1.45),buffer=audio.createBuffer(1,length,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/length,2);const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.setValueAtTime(950,audio.currentTime);filter.frequency.exponentialRampToValueAtTime(85,audio.currentTime+1.35);gain.gain.setValueAtTime(.65,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+1.45);source.connect(filter).connect(gain).connect(audio.destination);source.start()}
function hapticFeedback(intensity=.45,duration=160,strong=intensity){const pad=navigator.getGamepads?.()[0],actuator=pad?.vibrationActuator||pad?.hapticActuators?.[0];if(!actuator)return false;try{if(actuator.playEffect)actuator.playEffect('dual-rumble',{duration,startDelay:0,strongMagnitude:THREE.MathUtils.clamp(strong,0,1),weakMagnitude:THREE.MathUtils.clamp(intensity,0,1)});else actuator.pulse?.(THREE.MathUtils.clamp(intensity,0,1),duration);return true}catch{return false}}
