function setAirfieldLighting(key){const active=key==='night'||key==='fog'||key==='storm';for(const set of airfieldLightSets){set.bulbs.material.opacity=active?.98:.35;set.bulbs.material.size=active?1.8:1.1;set.glow.material.opacity=active?(key==='night'?1:.62):0;set.glow.material.size=key==='fog'?11:8.5}}
function applyWeather(key){
  if(key==='random')key=Object.keys(weatherProfiles)[Math.floor(Math.random()*Object.keys(weatherProfiles).length)];
  activeWeatherKey=key;activeWeather=weatherProfiles[key]||weatherProfiles.clear;document.body.classList.remove(...Object.keys(weatherProfiles).map(k=>`weather-${k}`),'lightning');document.body.classList.add(`weather-${key}`);scene.fog.near=key==='fog'?40:key==='storm'?180:key==='rain'?350:900;scene.fog.far=activeWeather.visibility;scene.fog.color.set(activeWeather.fog);scene.background.set(activeWeather.sky);renderer.setClearColor(activeWeather.sky);hemisphere.intensity=activeWeather.light;hemisphere.color.set(activeWeather.night?0x46658b:0xdff5ff);hemisphere.groundColor.set(activeWeather.night?0x172137:0x667453);sun.intensity=activeWeather.sun;sun.color.set(key==='storm'?0xbfd5e4:key==='night'?0x7890b8:0xfff2d1);cloudMat.color.set(activeWeather.cloudColor);cloudMat.opacity=activeWeather.cloudOpacity;clouds.forEach((cloud,i)=>{cloud.visible=i/clouds.length<activeWeather.clouds;const low=key==='storm'||key==='rain';cloud.position.y=(low?260:420)+cloud.userData.layer*(low?250:440)+Math.random()*80});precipitation.visible=activeWeather.rain>0;precipitation.material.opacity=.3+activeWeather.rain*.58;stars.visible=!!activeWeather.night;stars.position.set(state.x,0,state.z);skyOrb.visible=!activeWeather.night;moon.visible=moonHalo.visible=!!activeWeather.night;setAirfieldLighting(key);lightningTimer=2.5+Math.random()*4;$('#weatherBadge').textContent=`${activeWeather.icon} ${activeWeather.name} · 能见度 ${(activeWeather.visibility/1000).toFixed(1)} km · 风 ${activeWeather.wind} kt${activeWeather.gust?` 阵风 ${activeWeather.gust}`:''}`
}
function maybeFailure(dt){if(difficulty!=='failures'||activeFailure||state.onGround||state.flightSeconds<45)return;failureTimer+=dt;if(failureTimer<90+Math.random()*80)return;failureTimer=0;const failures=['generator','hydraulic','flaps','engine','pressurization','irs','fire'];activeFailure=failures[Math.floor(Math.random()*failures.length)];if(activeFailure==='generator'){state.gen1=false;toast('ELEC · GEN 1 OFF BUS');}else if(activeFailure==='hydraulic'){state.hydraulics=false;toast('HYD PRESS LOW');}else if(activeFailure==='flaps'){state.flaps=Math.min(state.flaps,2);toast('FLAPS DISAGREE');}else if(activeFailure==='pressurization'){state.pressurization=false;toast('CABIN ALTITUDE · PRESSURIZATION FAIL');}else if(activeFailure==='irs'){state.irsAligned=false;state.irsLeft=false;toast('IRS LEFT FAIL · 使用航向模式');}else if(activeFailure==='fire'){state.engineFire=true;toast('ENGINE FIRE · 切断推力并使用灭火手柄');speakCallout('ENGINE FIRE')}else{state.engines[Math.random()>.5?0:1]=0;toast('ENG FAIL · 检查发动机显示')}warningTone()}
function crash(reason){if(state.crashed)return;state.crashed=true;state.running=false;explosionSound();$('#explosionFlash').classList.add('show');const blast=new THREE.Group(),particles=[];for(let i=0;i<70;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.6+Math.random()*2.4,7,5),new THREE.MeshBasicMaterial({color:i%3===0?0x2b2420:i%2?0xff4a00:0xffc21c,transparent:true}));p.position.set((Math.random()-.5)*6,(Math.random()-.2)*5,(Math.random()-.5)*6);p.userData.velocity=new THREE.Vector3((Math.random()-.5)*44,8+Math.random()*38,(Math.random()-.5)*44);blast.add(p);particles.push(p)}blast.position.copy(aircraft.position);scene.add(blast);const flash=new THREE.PointLight(0xff4b00,65,700);flash.position.copy(aircraft.position);scene.add(flash);aircraft.visible=false;let life=0;const animateBlast=()=>{life+=.025;particles.forEach(p=>{p.position.addScaledVector(p.userData.velocity,.025);p.userData.velocity.y-=.75;p.material.opacity=Math.max(0,1-life/2.2);p.scale.multiplyScalar(1.012)});flash.intensity=Math.max(0,65-life*45);if(life<2.3)requestAnimationFrame(animateBlast);else{scene.remove(blast,flash)}};animateBlast();setTimeout(()=>{$('#crashReason').textContent=reason;ui.crash.classList.add('show')},650)}
function updateWorld(dt){for(const t of traffic){if(t.mode===0){t.model.rotation.y=0;t.z-=t.speed*dt;if(t.z<-3800)t.z=2100;t.y=2.8}else if(t.mode===1){t.model.rotation.y=0;t.z-=t.speed*dt;t.y=2.8+Math.min(1000,(1800-t.z)*.13);if(t.z<-12000){t.z=1800;t.y=2.8}}else{t.model.rotation.y=Math.PI;t.z+=t.speed*dt;t.y=t.z<-3600?2.8+(-3600-t.z)*.107:2.8;if(t.z>1800){t.z=-12000;t.y=902}}t.model.position.set(t.x,t.y,t.z);const horizontal=Math.hypot(state.x-t.x,state.z-t.z),vertical=Math.abs(state.y-t.y);if(horizontal<700&&vertical<90&&!state.onGround&&performance.now()-collisionWarningTimer>2600){toast(`TRAFFIC · 同高度飞机接近 · 高度差 ${Math.round(vertical)} m`);warningTone();collisionWarningTimer=performance.now()}if(horizontal<18&&vertical<8)crash('与其他飞机相撞，飞行结束')}for(const b of birds){b.model.position.x+=Math.sin(performance.now()/1800+b.phase)*b.speed*dt;b.model.position.z-=b.speed*dt;b.model.rotation.y+=dt*.3;if(b.model.position.z<-15000)b.model.position.z=2500;const horizontal=Math.hypot(state.x-b.model.position.x,state.z-b.model.position.z),vertical=Math.abs(state.y-b.model.position.y);if(horizontal<180&&vertical<45&&performance.now()-collisionWarningTimer>2200){toast('BIRD · 同高度鸟群接近');warningTone();collisionWarningTimer=performance.now()}if(horizontal<9&&vertical<5)crash('发生鸟击，飞行结束')}updateTerrainChunks();clouds.forEach(cloud=>{cloud.position.x+=activeWeather.wind*.018*dt;if(Math.abs(cloud.position.z-state.z)>13500)cloud.position.z=state.z-9000-Math.random()*4300;if(Math.abs(cloud.position.x-state.x)>7600)cloud.position.x=state.x+(Math.random()-.5)*12000});stars.position.set(state.x,0,state.z);const skyHeading=(state.heading-31)*Math.PI/180,skyDistance=6400,skyPosition=new THREE.Vector3(state.x+Math.sin(skyHeading)*skyDistance,state.y+3900,state.z-Math.cos(skyHeading)*skyDistance);skyOrb.position.copy(skyPosition);moon.position.copy(skyPosition);moonHalo.position.copy(skyPosition);moon.rotation.y+=dt*.006;if(precipitation.visible){precipitation.position.set(state.x,state.y+40,state.z);const positions=rainGeo.attributes.position.array,fall=activeWeatherKey==='storm'?280:210,drift=activeWeather.wind*1.2;for(let i=0;i<positions.length;i+=3){positions[i]+=drift*dt;positions[i+1]-=fall*dt;positions[i+2]+=35*dt;if(positions[i+1]<-100){positions[i]=(Math.random()-.5)*520;positions[i+1]=220+Math.random()*100;positions[i+2]=(Math.random()-.5)*520}}rainGeo.attributes.position.needsUpdate=true}if(activeWeather.lightning){lightningTimer-=dt;if(lightningTimer<=0){lightningLight.intensity=7;document.body.classList.add('lightning');setTimeout(()=>{lightningLight.intensity=0;document.body.classList.remove('lightning')},120);lightningTimer=4+Math.random()*8}}}

function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),2200)}
function initAudio(){if(audio)return;audio=new(window.AudioContext||window.webkitAudioContext)();engineOsc=audio.createOscillator();const rumble=audio.createOscillator(),filter=audio.createBiquadFilter(),compressor=audio.createDynamicsCompressor();engineGain=audio.createGain();engineOsc.type='sawtooth';engineOsc.frequency.value=54;rumble.type='sine';rumble.frequency.value=31;filter.type='lowpass';filter.frequency.value=260;engineGain.gain.value=0;engineOsc.connect(filter);rumble.connect(filter);filter.connect(engineGain).connect(compressor).connect(audio.destination);engineOsc.start();rumble.start();const noiseBuffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),d=noiseBuffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;const noise=audio.createBufferSource(),noiseFilter=audio.createBiquadFilter();engineNoiseGain=audio.createGain();noise.buffer=noiseBuffer;noise.loop=true;noiseFilter.type='bandpass';noiseFilter.frequency.value=420;noiseFilter.Q.value=.55;engineNoiseGain.gain.value=0;noise.connect(noiseFilter).connect(engineNoiseGain).connect(compressor);noise.start()}
function beep(freq=740,duration=.12){if(!state.sound)return;initAudio();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function starterSound(index){if(!state.sound)return;initAudio();const o=audio.createOscillator(),g=audio.createGain(),filter=audio.createBiquadFilter();o.type='sawtooth';o.frequency.setValueAtTime(70+index*4,audio.currentTime);o.frequency.exponentialRampToValueAtTime(185+index*7,audio.currentTime+4.5);filter.type='lowpass';filter.frequency.value=620;g.gain.setValueAtTime(.001,audio.currentTime);g.gain.exponentialRampToValueAtTime(.055,audio.currentTime+.3);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+5.2);o.connect(filter).connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+5.3)}
