  if(!state.bleed){toast(`ENGINE ${n} START 被拒绝：先打开 APU BLEED`);beep(210,.2);return}
  if(!aircraftSystemStatus().fuelPressure){toast(`ENGINE ${n} START 被拒绝：先打开左右燃油泵`);beep(210,.2);return}
  if(!state.beacon){toast(`ENGINE ${n} START 被拒绝：启动前必须打开 BEACON 防撞灯`);beep(210,.2);return}
  if(state.packs){toast(`ENGINE ${n} START 被拒绝：PACKS 必须 OFF，保证启动引气压力`);beep(210,.2);return}
  if(state.engineStarting[index]||state.engineData[index].phase==='STABLE')return;
