function activeTutorialSteps(){return tutorialKind==='panels'?panelTutorialSteps:tutorialSteps}
function clearTutorialTarget(){$$('.tutorial-target').forEach(e=>e.classList.remove('tutorial-target'))}
function clearTutorialAdvance(){if(tutorialAdvanceTimer!==null){clearTimeout(tutorialAdvanceTimer);tutorialAdvanceTimer=null}}
function placeTutorial(target){const card=$('#tutorial');card.style.top='';card.style.bottom='';card.style.left='50%';card.style.right='auto';card.style.transform='translateX(-50%)';if(!target)return;const r=target.getBoundingClientRect();if(r.top<innerHeight*.5){card.style.top='auto';card.style.bottom='18px'}else{card.style.top='75px';card.style.bottom='auto'}if(innerWidth>900&&r.left<innerWidth*.38){card.style.left='auto';card.style.right='18px';card.style.transform='none'}else if(innerWidth>900&&r.right>innerWidth*.62){card.style.left='18px';card.style.right='auto';card.style.transform='none'}}
function showTutorialStep(){clearTutorialAdvance();clearTutorialTarget();const steps=activeTutorialSteps(),step=steps[tutorialIndex];if(!step){finishTutorial();return}step.prepare?.();const informational=tutorialKind==='panels',done=!!step.done?.(),autoAdvance=!informational&&step.autoAdvance!==false;$('#tutorialProgress').textContent=`${informational?'驾驶舱面板导览':'冷舱启动教学'} ${tutorialIndex+1} / ${steps.length}`;$('#tutorialTitle').textContent=step.title;$('#tutorialText').textContent=step.text;$('#tutorialBack').disabled=tutorialIndex===0;$('#tutorialNext').classList.toggle('active',informational||done);$('#tutorialNext').textContent=tutorialIndex===steps.length-1?'完成':'下一步';const target=$(step.target);target?.classList.add('tutorial-target');placeTutorial(target);$('#tutorialHint').textContent=informational||step.autoAdvance===false?'阅读后点击下一步':done&&autoAdvance?'已完成，自动进入下一步…':'等待你完成操作…'}
function beginTutorial(kind){tutorialKind=kind;if(!state.running)begin(kind==='panels');tutorialActive=true;tutorialIndex=0;$('#tutorial').classList.remove('hidden');document.body.classList.remove('view-external');state.external=false;showTutorialStep()}
function startTutorial(){beginTutorial('startup')}
function startPanelTour(){beginTutorial('panels')}
function finishTutorial(){const panels=tutorialKind==='panels';tutorialActive=false;clearTutorialAdvance();clearTutorialTarget();closePopups();$('#tutorial').classList.add('hidden');toast(panels?'驾驶舱面板导览完成！':'冷舱启动教学完成！');localStorage.setItem(panels?'b738-panel-tour-complete':'b738-tutorial-complete','1')}
function monitorTutorial(){if(!tutorialActive||tutorialKind==='panels')return;const step=activeTutorialSteps()[tutorialIndex];if(!step?.done())return;$('#tutorialNext').classList.add('active');if(step.autoAdvance===false){$('#tutorialHint').textContent='阅读后点击下一步';return}$('#tutorialHint').textContent='已完成，自动进入下一步…';if(tutorialAdvanceTimer!==null)return;const completedIndex=tutorialIndex;tutorialAdvanceTimer=setTimeout(()=>{tutorialAdvanceTimer=null;if(!tutorialActive||tutorialKind!=='startup'||tutorialIndex!==completedIndex)return;const current=activeTutorialSteps()[tutorialIndex];if(!current?.done())return;tutorialIndex++;showTutorialStep()},850)}

function fireTest(){if(!state.battery){toast('FIRE TEST 不可用：BATTERY OFF');return}$('#fireWarn').classList.add('lit');$('#masterCaution').classList.add('lit');toast('FIRE / OVHT TEST · 警铃与指示灯测试');warningTone();setTimeout(()=>{$('#fireWarn').classList.remove('lit');$('#masterCaution').classList.remove('lit')},1800)}
function extinguishEngineFire(){if(!state.engineFire){toast('ENG EXTINGUISH · 当前没有发动机火警');return}state.engineFire=false;state.engines=[0,0];state.engineData.forEach(d=>{d.phase='OFF';d.n1=d.n2=0;d.egt=120});toast('ENGINE FIRE EXTINGUISHED · 双发已切断');speakCallout('ENGINE FIRE EXTINGUISHED')}
function hardwareTelemetry(){const coordinate=worldCoordinateFromPosition(state.x,state.z),systems=aircraftSystemStatus();return{protocol:'flight-simulator-telemetry-v1',time:Date.now(),aircraft:activeAircraft.id,latitude:+coordinate.lat.toFixed(6),longitude:+coordinate.lon.toFixed(6),ias:Math.round(state.ias),altitudeFt:Math.round(state.altitude),verticalSpeedFpm:Math.round(state.vs),heading:+state.heading.toFixed(1),pitch:+state.pitch.toFixed(2),roll:+state.roll.toFixed(2),aoa:+state.aoa.toFixed(2),throttle:Math.round(state.throttle),flaps:state.flaps,gear:state.gearDown?'DOWN':'UP',onGround:state.onGround,autopilot:state.ap.ap,stall:state.stallSeverity>.05,masterCaution:!systems.transfer||state.cabinAltitude>10000||state.gearDamaged,engines:state.engines.map(Math.round),fuelKg:Math.round(state.fuel)}}
function applyHardwareCommand(line){const clean=line.trim();if(!clean)return;let command,value;try{const data=JSON.parse(clean),axes=data.axes||data;if(['roll','pitch','rudder'].some(key=>Number.isFinite(+axes[key]))){for(const key of['roll','pitch','rudder'])if(Number.isFinite(+axes[key]))hardwareAxes[key]=THREE.MathUtils.clamp(+axes[key],-1,1);hardwareAxes.updatedAt=performance.now()}if('throttle'in data){command='THROTTLE';value=data.throttle}else if('flaps'in data){command='FLAPS';value=data.flaps}else if('gear'in data){command='GEAR';value=data.gear}else if(data.command){command=data.command;value=data.value}else if(['roll','pitch','rudder'].some(key=>Number.isFinite(+axes[key])))return}catch{[command,value]=clean.toUpperCase().split(/\s*=\s*|\s+/)}command=String(command||'').toUpperCase();if(['ROLL','PITCH','RUDDER'].includes(command)){hardwareAxes[command.toLowerCase()]=THREE.MathUtils.clamp(+value||0,-1,1);hardwareAxes.updatedAt=performance.now()}else if(command==='THROTTLE'){state.throttle=THREE.MathUtils.clamp(+value||0,0,100);ui.throttle.value=state.throttle;$('#throttleVal').textContent=state.throttle>90?'TO/GA':`${Math.round(state.throttle)}%`}else if(command==='FLAPS'){state.flaps=THREE.MathUtils.clamp(Math.round(+value||0),0,5);ui.flaps.value=state.flaps;$('#flapsVal').textContent=state.flaps?['','1','5','15','30','40'][state.flaps]:'UP'}else if(command==='GEAR'){const down=String(value).toUpperCase()==='DOWN'||value===true;if(down!==state.gearDown){if(!down&&state.onGround){toast('实体面板 GEAR UP 被拒绝：飞机仍在地面');return}setGear(down)}}else if(command==='AP'){String(value).toUpperCase()==='OFF'?disconnectAutopilot('实体面板断开自动驾驶'):state.ap.ap?disconnectAutopilot('实体面板断开自动驾驶'):startAutoLand()}else if(command==='VIEW'){$('#viewBtn').click()}else{const systemName={BATTERY:'battery',GROUNDPOWER:'groundPower',APU:'apuMaster',BEACON:'beacon',NAVLIGHTS:'navLights',STROBE:'strobe',LANDINGLIGHTS:'landingLights',HYDRAULICS:'hydraulics'}[command],button=systemName?$(`[data-switch="${systemName}"]`):null,on=['ON','1','TRUE'].includes(String(value).toUpperCase());if(button&&state[systemName]!==on)button.click()}}
async function readHardwarePanel(){const decoder=new TextDecoder();while(panelPort?.readable){panelReader=panelPort.readable.getReader();try{while(true){const{value,done}=await panelReader.read();if(done)break;panelReadBuffer+=decoder.decode(value,{stream:true});const lines=panelReadBuffer.split(/\r?\n/);panelReadBuffer=lines.pop()||'';lines.forEach(applyHardwareCommand)}}catch(error){if(panelPort)toast(`实体面板读取中断 · ${error.message}`)}finally{panelReader.releaseLock();panelReader=null}}}
async function connectHardwarePanel(){if(!('serial'in navigator)){toast('当前浏览器不支持 Web Serial，请使用最新版 Chrome 或 Edge');return}try{panelPort=await navigator.serial.requestPort();await panelPort.open({baudRate:115200});panelWriter=panelPort.writable.getWriter();updateHardwareStatus();readHardwarePanel();toast('实体面板已连接 · 115200 baud · 遥测输出已启动')}catch(error){panelPort=null;panelWriter=null;updateHardwareStatus();if(error.name!=='NotFoundError')toast(`实体面板连接失败 · ${error.message}`)}}
async function disconnectHardwarePanel(){const port=panelPort;panelPort=null;try{await panelReader?.cancel()}catch{}try{panelWriter?.releaseLock()}catch{}panelWriter=null;try{await port?.close()}catch{}updateHardwareStatus();toast('实体面板已断开')}
async function updateHardwareBridge(dt){if(!panelPort||!panelWriter)return;hardwareTelemetryTimer+=dt;if(hardwareTelemetryTimer<.1)return;hardwareTelemetryTimer=0;try{await panelWriter.write(new TextEncoder().encode(`${JSON.stringify(hardwareTelemetry())}\n`))}catch{disconnectHardwarePanel()}}
function downloadTelemetrySample(){const sample={telemetry:hardwareTelemetry(),acceptedCommands:['THROTTLE=80','FLAPS=2','GEAR=DOWN','AP=OFF','BATTERY=ON','VIEW=TOGGLE','ROLL=-0.5','PITCH=0.25','RUDDER=0.1'],jsonAxes:{axes:{roll:-0.5,pitch:0.25,rudder:0.1},throttle:80},axisRange:'-1.0 to +1.0',serial:{baudRate:115200,lineEnding:'LF',format:'UTF-8 JSON Lines'}},blob=new Blob([JSON.stringify(sample,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='flight-simulator-hardware-protocol.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('实体面板协议、摇杆轴与遥测样例已下载')}
$$('[data-switch]').forEach(b=>b.addEventListener('click',()=>toggleSystem(b.dataset.switch,b)));$$('[data-fuel-lever]').forEach(b=>b.addEventListener('click',()=>toggleFuelLever(+b.dataset.fuelLever,b)));$('[data-action="apuStart"]').onclick=startAPU;$('[data-action="startEng1"]').onclick=()=>startEngine(0);$('[data-action="startEng2"]').onclick=()=>startEngine(1);$('[data-action="fireTest"]').onclick=fireTest;$('[data-action="fireExtinguish"]').onclick=extinguishEngineFire;
