$('#deviceSettingsBtn').onclick=()=>{$('#systemsPanel').classList.remove('open');$('#devicePanel').classList.add('open')};function syncControlSettings(){controlConfig.deadzone=+$('#deadzoneControl').value/100;controlConfig.sensitivity=+$('#sensitivityControl').value/100;controlConfig.invertPitch=$('#invertPitch').checked;controlConfig.invertRudder=$('#invertRudder').checked;$('#deadzoneValue').textContent=`${Math.round(controlConfig.deadzone*100)}%`;$('#sensitivityValue').textContent=`${Math.round(controlConfig.sensitivity*100)}%`;localStorage.setItem('b738-control-config',JSON.stringify(controlConfig))}$('#deadzoneControl').value=Math.round(controlConfig.deadzone*100);$('#sensitivityControl').value=Math.round(controlConfig.sensitivity*100);$('#invertPitch').checked=controlConfig.invertPitch;$('#invertRudder').checked=controlConfig.invertRudder;$('#deadzoneControl').oninput=syncControlSettings;$('#sensitivityControl').oninput=syncControlSettings;$('#invertPitch').onchange=syncControlSettings;$('#invertRudder').onchange=syncControlSettings;$('#deviceReset').onclick=()=>{$('#deadzoneControl').value=8;$('#sensitivityControl').value=100;$('#invertPitch').checked=false;$('#invertRudder').checked=false;syncControlSettings();toast('外设校准已恢复默认')};$('#deviceClose').onclick=()=>{syncControlSettings();$('#devicePanel').classList.remove('open');toast('外设设置已保存')};syncControlSettings();
